    <?php if ($editingMovie || $preview): ?><section class="admin-panel upload-panel" aria-labelledby="upload-title"><div class="panel-heading"><div><span class="eyebrow">EL MATERIAL DE LA FUNCIÓN</span><h2 id="upload-title">Archivos del contenido</h2></div><span class="panel-step">02 <span>/ PORTADA Y VIDEOS</span></span></div><p class="upload-intro">Para publicar, carga una portada y al menos un video: tráiler o película completa. El enlace de origen y la referencia de derechos son opcionales.</p><div class="upload-grid"><?php foreach ($uploadSlots as $uploadKind => $slot): ?>
    <form class="upload-card" data-upload-form data-movie-id="<?= (int) ($editingMovie['id'] ?? 0) ?>" data-kind="<?= e($uploadKind) ?>" data-max-bytes="<?= (int) $uploadLimits[$uploadKind] ?>" data-init-url="<?= e(url('/upload/iniciar')) ?>" data-part-url="<?= e(url('/upload/parte')) ?>" data-complete-url="<?= e(url('/upload/completar')) ?>" data-cancel-url="<?= e(url('/upload/cancelar')) ?>" action="<?= e(url('/upload/iniciar')) ?>" method="post" enctype="multipart/form-data">
        <?= csrf_field() ?><fieldset <?= $preview ? 'disabled' : '' ?>><div class="upload-card-heading"><span class="upload-icon"><?= cf_icon($slot['icon']) ?></span><div><h3><?= e($slot['label']) ?></h3><p><?= e($slot['hint']) ?></p></div></div>
        <?php $slotExists = $uploadKind === 'portada' ? !empty($editingMovie['has_poster']) : ($uploadKind === 'trailer' ? !empty($editingMovie['has_trailer']) : !empty($editingMovie['has_movie'])); ?>
        <p class="upload-current <?= $slotExists ? 'file-ready' : '' ?>"><?= cf_icon($slotExists ? 'check' : 'info') ?><?= $slotExists ? 'Archivo cargado · puedes reemplazarlo' : ($uploadKind === 'portada' ? 'Necesaria para publicar' : ($uploadKind === 'pelicula' ? 'Alternativa al tráiler · acceso con cuenta' : 'Opcional si cargas la película completa')) ?></p><div class="field"><label class="file-label" for="file-<?= e($uploadKind) ?>"><?= cf_icon('upload') ?> Seleccionar archivo</label><input type="file" id="file-<?= e($uploadKind) ?>" name="archivo" accept="<?= e($slot['accept']) ?>" required></div><div class="field"><label for="source-<?= e($uploadKind) ?>">Enlace de origen (opcional)</label><input id="source-<?= e($uploadKind) ?>" name="fuente_url" type="url" placeholder="https://archive.org/details/…" maxlength="2048"></div><div class="field"><label for="rights-<?= e($uploadKind) ?>">Referencia de derechos (opcional)</label><textarea id="rights-<?= e($uploadKind) ?>" name="referencia_derechos" rows="2" placeholder="Fuente, licencia y versión del archivo" maxlength="4000"></textarea></div><progress data-upload-progress value="0" max="100" hidden aria-label="Progreso de carga de <?= e($slot['label']) ?>"></progress><p data-upload-status class="upload-status" role="status" aria-live="polite"></p><div class="upload-buttons"><button type="submit" class="button button-outline button-small"><?= cf_icon('upload') ?> Cargar <?= e(mb_strtolower($slot['label'])) ?></button><button type="button" class="text-button" data-upload-cancel hidden>Cancelar</button></div></fieldset>
    </form><?php endforeach ?></div><p class="upload-footnote"><?= cf_icon('lock') ?>Los archivos se guardan de forma privada. Verifica los derechos de la versión que vas a publicar.</p></section><?php endif ?>
